{
  "name": "Postman领域模型",
  "description": "用于 Query Intelligence",
  "entities": [
    {
      "name": "Employee"
    },
    {
      "name": "ExpensePolicy"
    }
  ],
  "relations": [
    {
      "from": "Employee",
      "to": "ExpensePolicy",
      "type": "subject_to"
    }
  ],
  "terms": [
    {
      "canonical": "报销",
      "aliases": [
        "费用报销",
        "expense reimbursement"
      ]
    },
    {
      "canonical": "差旅",
      "aliases": [
        "出差",
        "business travel"
      ]
    }
  ],
  "extraction_policy": {
    "language": "zh-CN"
  }
}

{
  "name": "Postman知识应用",
  "description": "v2.4 product release validation",
  "answer_model": null,
  "knowledge_set_ids": [
    "{{set_id}}"
  ]
}

{
  "query_intelligence_policy": {
    "enabled": true
  },
  "provider_policy": {
    "semantic": true,
    "graph": true,
    "artifact": true
  },
  "provider_weights": {
    "semantic": 1.0,
    "graph": 0.9,
    "outline": 0.8,
    "table": 0.9
  },
  "candidate_budget": {
    "total": 64
  },
  "fanout_budget": {
    "max_kbs": 8,
    "max_providers_per_kb": 4
  },
  "latency_budget": {
    "total_ms": 5000
  },
  "fallback_policy": {
    "mode": "semantic"
  },
  "artifact_policy": {
    "outline": true,
    "table": true
  },
  "fusion_policy": {
    "strategy": "weighted_rrf",
    "k": 60
  },
  "notes": "Postman v2.4 validation"
}
